preConditionHook:
// The level for a candidate breakout bar kk is the extreme of bars
// kk+1 .. kk+rangeBars -- Lowest(l, rangeBars)[kk + 1] in EasyLanguage, which
// the twin open-codes because that is a history reference on a function call at
// a VARIABLE offset. Extremes(), which Highest and Lowest call, is EL source and
// is exactly this loop: seed at the first bar of the window and scan the rest
// with a strict, tolerance-carrying comparison (see Breakout), so seed at offset
// kk+1 and scan kk+2 .. kk+rangeBars with el_gt/el_lt.
brokeDown = false;
brokeUp = false;
for (int k = 1; k <= (int)failBars; ++k) {
    double lvlLow = low[k + 1];
    double lvlHigh = high[k + 1];
    for (int j = k + 2; j <= k + (int)rangeBars; ++j) {
        if (el_lt(low[j], lvlLow)) lvlLow = low[j];
        if (el_gt(high[j], lvlHigh)) lvlHigh = high[j];
    }
    if (el_lt(close[k], lvlLow) && el_gt(close[0], lvlLow)) brokeDown = true;
    if (el_gt(close[k], lvlHigh) && el_lt(close[0], lvlHigh)) brokeUp = true;
}
